UPDATE stm_codelist SET cod_system = 1 WHERE cod_list = 'databaseConnection.driver' AND cod_value = 'oracle.jdbc.OracleDriver';
INSERT INTO stm_codelist (cod_id, cod_list, cod_value, cod_system, cod_default, cod_description) SELECT COALESCE((SELECT MAX(cod_id) FROM stm_codelist), 0) + 1, 'databaseConnection.driver', 'oracle.jdbc.OracleDriver', 1, 0, CASE COALESCE((SELECT cnf_value FROM stm_conf WHERE cnf_name = 'language.default'), 'en') WHEN 'ca' THEN 'Controlador JDBC Oracle' WHEN 'es' THEN 'Controlador JDBC Oracle' WHEN 'fr' THEN 'Pilote JDBC Oracle' WHEN 'oc-aranes' THEN 'Controlador JDBC Oracle' ELSE 'Oracle JDBC driver' END FROM dual WHERE NOT EXISTS (SELECT 1 FROM stm_codelist WHERE cod_list = 'databaseConnection.driver' AND cod_value = 'oracle.jdbc.OracleDriver');
UPDATE stm_codelist SET cod_system = 1 WHERE cod_list = 'databaseConnection.driver' AND cod_value = 'com.microsoft.sqlserver.jdbc.SQLServerDriver';
INSERT INTO stm_codelist (cod_id, cod_list, cod_value, cod_system, cod_default, cod_description) SELECT COALESCE((SELECT MAX(cod_id) FROM stm_codelist), 0) + 1, 'databaseConnection.driver', 'com.microsoft.sqlserver.jdbc.SQLServerDriver', 1, 0, CASE COALESCE((SELECT cnf_value FROM stm_conf WHERE cnf_name = 'language.default'), 'en') WHEN 'ca' THEN 'Controlador JDBC Microsoft SQL Server' WHEN 'es' THEN 'Controlador JDBC Microsoft SQL Server' WHEN 'fr' THEN 'Pilote JDBC Microsoft SQL Server' WHEN 'oc-aranes' THEN 'Controlador JDBC Microsoft SQL Server' ELSE 'Microsoft SQL Server JDBC Driver' END FROM dual WHERE NOT EXISTS (SELECT 1 FROM stm_codelist WHERE cod_list = 'databaseConnection.driver' AND cod_value = 'com.microsoft.sqlserver.jdbc.SQLServerDriver');
